// Email Triage Assistant: core logic (ported from main.py)

// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

const VIPS = ['ceo@acme.ng', 'mrs.ade@brightschools.ng'];
const CATS = { invoice: ['invoice', 'payment', 'receipt', 'bill'], meeting: ['meeting', 'call', 'schedule', 'calendar', 'zoom', 'available'],
  newsletter: ['unsubscribe', 'newsletter', 'weekly digest', 'webinar'], client: ['proposal', 'contract', 'project', 'quote', 'deliverable'] };
const URGENT = ['urgent', 'asap', 'today', 'by eod', 'deadline', 'immediately', 'overdue'];
const PHISH = ['verify your account', 'password expires', 'click here to avoid', 'gift card'];
const DRAFT = { meeting: 'thanks. Tuesday or Wednesday after 2pm works for me. Which suits you?',
  invoice: "thanks for this. I've forwarded it to finance and will confirm payment timing shortly.",
  client: "thanks for the update. I'll review and come back to you by end of day." };
const out = [];
for (const e of input) {
  const text = `${e.subject} ${e.body}`.toLowerCase(), sender = (e.from || '').toLowerCase(), domain = sender.split('@')[1] || '';
  if (PHISH.some(p => text.includes(p)) || /(paypa1|g00gle|micros0ft)/.test(domain)) {
    out.push({ route: 'Phishing', from: e.from, subject: e.subject, category: 'phishing', priority: 0 }); continue; }
  const cat = Object.keys(CATS).find(c => CATS[c].some(w => text.includes(w))) || 'other';
  let p = 2 + (VIPS.includes(sender) ? 3 : 0) + (URGENT.some(u => text.includes(u)) ? 2 : 0) + ((e.body || '').includes('?') ? 1 : 0);
  if (cat === 'newsletter' || /no-?reply/.test(sender)) p -= 3;
  const bucket = p >= 6 ? 'Act now' : p >= 3 ? 'Reply today' : p >= 0 ? 'Read later' : 'Ignore / report';
  const name = sender.split('@')[0].split('.')[0]; const first = name.charAt(0).toUpperCase() + name.slice(1);
  out.push({ route: bucket, from: e.from, subject: e.subject, category: cat, priority: p,
             draft: `Hi ${first}, ${DRAFT[cat] || "thanks for your email. I'll get back to you shortly."}` });
}
return out.map(json => ({ json }));
